public static int countDoubles(int[] numbers) {
    // Initialize a counter for doubles
    int count = 0;
    // Create a Set to store seen numbers to manage duplicates
    HashSet<Integer> seen = new HashSet<>();

    // Iterate through the array
    for (int number : numbers) {
        // Check if the number is already seen and is twice the current number
        if (seen.contains(number / 2)) {
            count++;
        }
        // Add the current number to the set
