}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // check input validity
    if (start == null || start.length != 2 || end == null || end.length != 2 || paths == null || paths.length < 1) {
        throw new IllegalArgumentException("Invalid input");
    }
    // find starting point
    int startX = start[0], startY = start[1];
    // find ending point
    int endX = end[0], endY = end[1];
    // traverse paths
    Set<String> visited = new HashSet<>();
    Queue<int[]> queue = new ArrayDeque<>();
    queue.offer(new int[]{startX, startY});
    visited.add(startX + "," + startY);
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == endX && current[1] == endY) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            int x = current[0] + path[0], y = current[1] + path[1];
            if (x >= 0 && x < n && y >= 0 && y < n && !visited.contains(x + "," + y)) {
                visited.add(x + "," + y);
                queue.offer(new int[]{x, y});
            }
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int commonChars = IntStream.range(0, Math.min(word1.length(), word2.length()))
                              .filter(i -> word1.charAt(i) == word2.charAt(i))
                              .count();
    int totalChars = word1.length() + word2.length();
    int gcd = gcd(commonChars, totalChars);
    return String.format("appx(%s, %s) = %d/%d", word1, word2, commonChars / gcd, totalChars / gcd);
}

private static int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

