public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Set<Integer> visited = new HashSet<>();
        return dfs(edges, hasApple, 0, visited);
    }

private int dfs(int[][] edges, boolean[] hasApple, int node, Set<Integer> visited) {
        visited.add(node);
        int minTime = 0;
        for (int[] edge : edges) {
            if (edge[0] == node && !visited.contains(edge[1])) {
                if (dfs(edges, hasApple, edge[1], visited)) {
                    minTime += (2 + dfs(edges, hasApple, edge[1], visited));
                }
            } else if (edge[1] == node && !visited.contains(edge[0])) {
                if (dfs(edges, hasApple, edge[0], visited)) {
                    minTime += (2 + dfs(edges, hasApple, edge[0], visited));
                }
            }
        }
        if (node != 0 && (hasApple[node] || anyChildDfs)) {
            minTime++;
        }
        return minTime;
    }

private boolean anyChildDfs(int[][] edges, boolean[] hasApple, int node, Set<Integer> visited) {
        visited.add(node);
        boolean anyChild = false;
        for (int[] edge : edges) {
            if (edge[0] == node && !visited.contains(edge[1])) {
                anyChild |= dfs(edges, hasApple, edge[1], visited);
            } else if (edge[1] == node && !visited.contains(edge[0])) {
                anyChild |= dfs(edges, hasApple, edge[0], visited);
            }
        }
        return anyChild;
    }

public String sortString(String s) {
    int[] charCount = new int[26];
    int maxCharCount = 0, minCharCount = 26;

    // Count the occurrences of each character
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
        maxCharCount = Math.max(maxCharCount, charCount[c - 'a']);
        minCharCount = Math.min(minCharCount, charCount[c - 'a']);
    }

    // Validate if all characters are unique
    if (maxCharCount > s.length() || minCharCount != 1) {
        throw new IllegalArgumentException("Input string does not meet the sorting criteria.");
    }

    StringBuilder result = new StringBuilder();
    int[] indexMap = new int[26];
    Arrays.fill(indexMap, 26);

    // Place the smallest characters first
    for (int i = 0; i < 26; i++) {
        while (charCount[i] > 0 && indexMap[i] < maxCharCount) {
            result.append((char) (i + 'a'));
            indexMap[i]++;
            charCount[i]--;
        }
    }

    // Place the largest characters second
    for (int i = 25; i >= 0; i--) {
        while (charCount[i] > 0 && indexMap[i] < maxCharCount) {
            result.append((char) (i + 'a'));
            indexMap[i]++;
            charCount[i]--;
        }
    }

    return result.toString();
}

public static boolean splitArraySameAverage(int[] nums) {
        if (nums == null || nums.length < 2) {
            throw new IllegalArgumentException("Array must contain at least two elements.");
        }

        int sum = Arrays.stream(nums).sum();
        int avg = sum / nums.length;

        for (int i = 0; i < nums.length - 1; i++) {
            if ((sum - nums[i]) % (nums.length - 1) != 0) {
                continue;
            }
            if (Arrays.stream(nums, i + 1, nums.length).average().equals(avg)) {
                return true;
            }
        }
        return false;
    }

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int prev1 = cost[0];
    int prev2 = cost[1];
    int current;

    for (int i = 2; i < n; i++) {
        current = Math.min(prev1 + cost[i], prev2 + cost[i]);
        prev1 = prev2;
        prev2 = current;
    }

    return prev2;
}

