public int minInsertions(String s) {
    int count = 0; // This variable will keep track of the balance of brackets
    int insertions = 0; // This variable will keep track of the number of extra closing brackets

    for (char c : s.toCharArray()) {
        if (c == '(') {
            count++;
        } else if (c == ')') {
            // If the current character is ')', decrementer from count
            if (count == 0) {
                // If count becomes 0, it means there's an extra closing bracket
                insertions++;
            } else {
                // Decrement count as we encounter another closing bracket after an open bracket
                count--;
            }
        }
    }

    // Since we need to have an equal number of open and close brackets,
    // the remaining count must be additional closing brackets (subtracted by insertions) needed to make balanced
    return count + insertions;
}

