public int findMinFibonacciNumbers(int k) {
        if (k <= 1) return k;
        int[] fib = {1, 1};
        while (true) {
            int next = fib[fib.length - 1] + fib[fib.length - 2];
            if (next > k) break;
            fib = Arrays.copyOf(fib, fib.length + 1);
            fib[fib.length - 1] = next;
        }
        int count = 0;
        for (int i = fib.length - 1; i >= 0 && k > 0; i--) {
            while (fib[i] <= k) {
                count++;
                k -= fib[i];
            }
        }
        return count;
    }

