public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> supportedNumbers = new ArrayList<>();
        String lowestString = String.valueOf(low);
        String highestString = String.valueOf(high);
        int n = highestString.length() - lowestString.length() + 1;

        for (int step = 0; step < n; step++) {
            findSteppingNumbersRecursive(lowestString, highestString, step, supportedNumbers);
        }

        Collections.sort(supportedNumbers);
        return supportedNumbers;
    }

private static void findSteppingNumbersRecursive(String lowestString, String highestString, int step, List<Integer> supportedNumbers) {
        if (step == 0) {
            String currentString = lowestString;
            if (currentString.length() == highestString.length()) {
                int num = Integer.parseInt(currentString);
                if (num >= low && num <= high) {
                    supportedNumbers.add(num);
                }
            }
            return;
        }

        int possibleNextCharacter = Character.getNumericValue(lowestString.charAt(step - 1)) + 1;
        if (possibleNextCharacter <= Character.getNumericValue(highestString.charAt(step - 1))) {
            findSteppingNumbersRecursive(lowestString, highestString, step + 1, supportedNumbers);
        }

        possibleNextCharacter = Character.getNumericValue(lowestString.charAt(step - 1)) - 1;
        if (possibleNextCharacter >= Character.getNumericValue(highestString.charAt(step - 1)) && possibleNextCharacter > 0) {
            findSteppingNumbersRecursive(lowestString, highestString, step + 1, supportedNumbers);
        }
    }

public static int countDigitOne(int n) {
    int count = 0, power = 1;

    while (n / power > 0) {
        int current = (n / power) % 10;
        int higher = n / (power * 10);

        switch (current) {
            case 0:
                count += higher * power;
                break;
            case 1:
                count += higher * power + n % power + 1;
                break;
            case 2:
                count += higher * power + n % power;
                break;
            default:
                count += (higher + 1) * power;
        }

        power *= 10;
    }

    return count;
}

public static boolean isPowerOfTwo(int n) {
