        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    while (n > 1) {
        if (n % 2 != 0) {
            return false;
        }
        n /= 2;
    }

    return true;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        throw new IllegalArgumentException("Input matrix must not be null or empty");
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[][] horizontal = new int[rows][cols];
    int[][] vertical = new int[rows][cols];
    int[][] diagonal = new int[rows][cols];
    int[][] antiDiagonal = new int[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = j > 0 ? horizontal[i][j - 1] + 1 : 1;
                vertical[i][j] = i > 0 ? vertical[i - 1][j] + 1 : 1;
                diagonal[i][j] = i > 0 && j > 0 ? diagonal[i - 1][j - 1] + 1 : 1;
                antiDiagonal[i][j] = i > 0 && j < cols - 1 ? antiDiagonal[i - 1][j + 1] + 1 : 1;
            }
        }
    }

    int maxLength = 0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            maxLength = Math.max(maxLength, horizontal[i][j], vertical[i][j], diagonal[i][j], antiDiagonal[i][j]);
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
    if(n == 0) {
        return "0";
    }

    // Convert the number to a string to facilitate manipulation
    String numStr = String.valueOf(n);

    // Reverse the string to simplify adding separators
    String reversed = new StringBuilder(numStr).reverse().toString();

    // Initialize theStringBuilder to store the result
    StringBuilder result = new StringBuilder();

    // Loop through the reversed string
    for(int i = 0; i < reversed.length(); i++) {
        // Add the current digit to result
        result.append(reversed.charAt(i));

        // Add a comma if the current digit is not the first digit
        if(i % 3 != 0 && i != 0) {
            result.append('.');
        }
    }

    // Reverse the result string back to its original order
    return new StringBuilder(result.reverse().toString()).toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n <= 1) {
        return n;
    }

    boolean[] used = new boolean[n];
    int count = 0;
    int[] swaps = new int[n];
    int swapsIndex = 0;

    // Helper function to calculate if a sum square is valid
    boolean isSumSquare(int sum) {
        int sqrt = (int) Math.sqrt(sum);
        return sqrt * sqrt == sum;
    }

    // Base case for the recursive function
    public void helper(int[] A, int[] swaps, int swapsIndex, int count) {
        if (swapsIndex == n) {
            count++;
            return;
        }

        for (int i = 0; i < n; i++) {
            if ( !used[i] && isSumSquare(A[i] + A[swaps[swapsIndex]]) ){
                used[i] = true;
                swaps[swapsIndex] = i;
                helper(A, swaps, swapsIndex + 1, count);
                used[i] = false;
            }
        }
    }

    helper(A, swaps, swapsIndex, count);
    return count;
}

