public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];

    // Find the nearest smaller element on the left of each bar
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        leftSmaller[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }

    // Find the nearest smaller element on the right of each bar
    stack.clear();
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        rightSmaller[i] = stack.isEmpty() ? heights.length : stack.peek();
        stack.push(i);
    }

    // Calculate the maximum area
    for (int i = 0; i < heights.length; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        maxArea = Math.max(maxArea, heights[i] * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int totalElements = rows * cols;
    int[] result = new int[totalElements];
    int curRow = 0;
    int curCol = 0;
    int direction = 1; // 1 for down, -1 for up

    for (int i = 0; i < totalElements; i++) {
        result[i] = mat[curRow][curCol];
        int nextRow = curRow + direction;
        int nextCol = curCol + direction;

        if (nextRow >= rows || nextRow < 0 || nextCol >= cols || nextCol < 0) {
            if (direction == 1) {
                curRow++;
                if (curRow == rows) {
                    curCol++;
                }
            } else {
                curCol++;
                if (curCol == cols) {
                    curRow++;
                }
            }
            direction = -direction; // Change direction
        } else {
            curRow = nextRow;
            curCol = nextCol;
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
        // Convert the integer to a char array for manipulation
        char[] digits = String.valueOf(n).toCharArray();
        int length = digits.length;

        // Start by checking if there is any digit that is less than the digit next to it
        for (int i = 0; i < length - 1; i++) {
            for (int j = i + 1; j < length; j++) {
                // If we find a digit that is less than its next neighbor, proceed
                if (digits[i] > digits[j]) {
                    // Swap the two digits
                    char temp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = temp;
                    // Sort the remaining digits to get the smallest possible number
                    Arrays.sort(digits, i + 1, length);
                    // Convert the sorted char array back to an integer and return
                    return Integer.parseInt(new String(digits));
                }
            }
        }

        // If no such pair is found, return -1
        return -1;
    }

public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerSymmetricNumbers = new ArrayList<>();
    if (n == 1) {
        centerSymmetricNumbers.add("0");
        centerSymmetricNumbers.add("1");
        centerSymmetricNumbers.add("8");
    } else {
        centerSymmetricNumbers.add(String.valueOf((int) Math.pow(10, n - 1)));
        for (int i = 1; i <= Math.pow(10, n - 1); i++) {
            String numStr = String.valueOf(i);
            int realLength = numStr.length();
            int middleIndex = realLength / 2;
            if (realLength - 1 % 2 == 0) {
                String leftPart = numStr.substring(0, middleIndex);
                String rightPart = new StringBuilder(numStr.substring(middleIndex)).reverse().toString();
                centerSymmetricNumbers.add(String.valueOf(Integer.parseInt(leftPart + rightPart)));
            } else {
                String leftPart = numStr.substring(0, middleIndex);
                String rightPart = numStr.substring(middleIndex + 1).reverse().toString();
                centerSymmetricNumbers.add(String.valueOf(Integer.parseInt(leftPart + rightPart)));
            }
        }
    }
    return centerSymmetricNumbers;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3 || points[0] == points[1] || points[1] == points[2]) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    if (x1 == x2 || x2 == x3 || x1 == x3) {
        return false;
    }

    double slopeA = (y2 - y1) / (double) (x2 - x1);
    double slopeB = (y3 - y2) / (double) (x3 - x2);
    double slopeC = (y1 - y3) / (double) (x1 - x3);

    if (slopeA == slopeB || slopeA == slopeC || slopeB == slopeC) {
        return false;
    }

    return true;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be positive");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int[] indices = {0, 0, 0}; // Indices for 2, 3, and 5

    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[indices[0]] * 2, Math.min(uglyNumbers[indices[1]] * 3, uglyNumbers[indices[2]] * 5));
        uglyNumbers[i] = min;
        switch (min) {
            case uglyNumbers[indices[0]] * 2:
                indices[0]++;
                break;
            case uglyNumbers[indices[1]] * 3:
                indices[1]++;
                break;
            case uglyNumbers[indices[2]] * 5:
                indices[2]++;
                break;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int maxLength = 0;
    int currentLength = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
        }
    }

    maxLength = Math.max(maxLength, currentLength);
    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> order = new ArrayList<>();
        generateOrder(order, 1, n);
        return order;
    }

private static void generateOrder(List<Integer> order, int current, int limit) {
        if (current > limit) return;
        order.add(current);
        generateOrder(order, current * 10, limit);
        if (current % 10 != 9) generateOrder(order, current + 1, limit);
    }

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>(Arrays.asList(nums));
    int sum = 0;
    for (Integer num : uniqueElements) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = i; // Initialize minimum with the number itself
        for (int j = 1; j * j <= i; j++) {
            min = Math.min(min, dp[i - j * j] + 1);
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.length() == 0) {
        return "";
    }

    StringBuilder result = new StringBuilder();
    String[] words = s.split(" ");

    for (String word : words) {
        // Reverse the character of each word
        StringBuilder reversedWord = new StringBuilder(word);
        reversedWord.reverse();
        result.append(reversedWord).append(" ");
    }

    // Remove the trailing space
    result.deleteCharAt(result.length() - 1);
    return result.toString();
}
